// TH15 Extra Stage7 Boss1 non-spell, st07bs.ecl.txt:44-66 (Boss1) + 118-153 (Boss1_at).
// Source entry state comes from st07bs.ecl.txt:8-39 (Boss): (0,128), hurt 40/2,
// hit 48/2, limit (0,128,280,64). Presentation/chapter/UI and the BossCard1
// hand-off are outside this card; the phase timer is the end boundary.
const TIME_LIMIT: int = 3724;       // 120 opening + 3600 source window + 4 startup
const OPENING_BUFFER: int = 120;
const TH15_KUNAI: int = 496;        // source etSprite type 9, color 4
const DELTA_A: int = 237;           // 0.022689281 rad
const DELTA_B: int = 291;           // 0.027925268 rad
const FAN_STEP: int = 40503;        // 3.883222 rad
const HALF_DELTA_A: int = 118;      // 0.5 * DELTA_A, mode10 layer offset
const HALF_DELTA_B: int = 146;      // 0.5 * DELTA_B, mode10 layer offset
const BIRTH_PUSH: fx = 12fx;        // etDist 24 minus ANIM a=1 retreat 4*3

// st07bs.ecl.txt:132-151. Boss1_at is async in the source; its two runs of
// ten 5-frame bursts continue while the boss task waits and then moves.
async sub boss1_at() {
    sh_reset(0);
    sh_sprite(0, TH15_KUNAI, 4);
    sh_speed(0, 3fx, 0fx);          // source etSpeed(0,3,3) before each etOn
    sh_count(0, 1, 1);
    sh_dist(0, BIRTH_PUSH);         // etDist(24) along angle, ANIM a=1 -4*3

    // mode10, N=25, M=2: q=0/1 have the same half-delta H and speed 3.
    var alpha: int = rand(65536) - 32768; // %RANDRAD
    for burst in 0..10 {                   // $B = 10
        for q in 0..2 {                    // layers outer, roads inner
            for i in 0..25 {
                var a: int = (i * 65536) / 25 + HALF_DELTA_A;
                if q % 2 != 0 { a = -a; }
                sh_angle(0, (alpha + a) as angle, 0deg);
                sh_fire(0);
            }
        }
        alpha = alpha + FAN_STEP;          // %C += 3.883222
        wait(5);
    }
    wait(10);
    alpha = rand(65536) - 32768;           // second %RANDRAD
    for burst2 in 0..10 {                  // $D = 10
        for q2 in 0..2 {
            for i2 in 0..25 {
                var a2: int = (i2 * 65536) / 25 + HALF_DELTA_B;
                if q2 % 2 != 0 { a2 = -a2; }
                sh_angle(0, (alpha + a2) as angle, 0deg);
                sh_fire(0);
            }
        }
        alpha = alpha - FAN_STEP;          // %C -= 3.883222
        wait(5);
    }
}

// st07bs.ecl.txt:412 moveRand(60,4,1.9), with moveLimit(0,128,280,64).
// The amplitude mode does not override the inherited linear speed slot:
// speed(k) = 1.9 * (60-k)/60, clamped each tick (not reflected).
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }      // x center 0, width 280
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }          // y center 128, height 64
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();                 // source t=0 movement tick
}

// True direction/limit recipe (TH16 movement chapter). The direction inner
// rectangle is center +- width/4, i.e. x +-70 and y 112..144.
sub card_move_rand() {
    var r: int = rand(65536) - 32768;     // signed RANDRAD in BAM
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// st07bs.ecl.txt:44-66. timerReset/setInterrupt/UI are represented by the
// phase timer; the source's initial wait(60) and spawn/wait/move/wait loop stay.
async sub boss1() {
    set_invuln(65535);
    // Boss entry flags end at 0x4C (offscreen-cull bits plus an unknown bit);
    // the boss never leaves its limit, and target has no matching flag write.
    set_hurtbox(20fx);                    // source 40/2
    set_hitbox(24fx);                     // source 48/2; body collision stays on
    wait(60);
    // The source setInterrupt time is 3600: entry wait60 plus 23 starts at
    // 60+160*n (last 3580) cover every Boss1_at begun inside the window.
    for cycle in 0..23 {
        spawn boss1_at();
        wait(100);
        card_move_rand();
        for i in 0..60 {
            wait(1);
            card_arm_next_step();
        }
    }
}

// Independent invincible shell: the control enemy has no body and owns the
// phase; the real boss is created after the 120-frame opening buffer.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 20000, 0, 0, 0, boss1);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
